```js
(async()=>{
  eval(await (await fetch('https://cdnjs.cloudflare.com/ajax/libs/jszip/3.10.1/jszip.min.js')).text());
  let x=0;
  for(const u of ['https://cors-get-proxy.sirjosh.workers.dev/?url=https://www.skyislandjournal.com/s/Andrea-Damic_Creative-Nonfiction_All-It-Takes-Is-a-Microscopic-Moment-in-Time-zzpm.docx',
